exemples.code:
import("stdfaust.lib");
// Un son pur : une seule fréquence
freq = hslider("freq [unit:Hz]", 440, 50, 2000, 1);
volume = hslider("volume", 0.3, 0, 1, 0.01) : si.smoo;
process = os.osc(freq) * volume <: _, _;

import("stdfaust.lib");
freq = hslider("freq [unit:Hz]", 220, 50, 1000, 1);
forme = nentry("forme [style:menu{'sinus':0;'triangle':1;'carrée':2;'dent de scie':3}]", 0, 0, 3, 1);
volume = hslider("volume", 0.25, 0, 1, 0.01) : si.smoo;
onde = os.osc(freq), os.triangle(freq), os.square(freq), os.sawtooth(freq) : ba.selectn(4, forme);
process = onde * volume <: _, _;

import("stdfaust.lib");
freq = hslider("freq [unit:Hz]", 440, 100, 1000, 1);
ecart = hslider("écart [unit:Hz]", 3, 0, 30, 0.1);
process = (os.osc(freq) + os.osc(freq + ecart)) * 0.2 <: _, _;

import("stdfaust.lib");
freq = hslider("freq", 440, 50, 2000, 0.01);
gate = button("gate");
a = hslider("attaque [unit:s]", 0.01, 0.001, 2, 0.001);
d = hslider("déclin [unit:s]", 0.3, 0.001, 2, 0.001);
s = hslider("maintien", 0.5, 0, 1, 0.01);
r = hslider("relâche [unit:s]", 0.5, 0.001, 4, 0.001);
process = os.sawtooth(freq) * en.adsr(a, d, s, r, gate) * 0.25 : fi.lowpass(2, 3000) <: _, _;

import("stdfaust.lib");
f = hslider("fondamentale [unit:Hz]", 110, 50, 400, 1);
partiel(i) = os.osc(f * (i + 1)) * hslider("h%j", 1 / (i + 1), 0, 1, 0.01) with { j = i + 1; };
process = par(i, 8, partiel(i)) :> _ * 0.12 <: _, _;

import("stdfaust.lib");
freq = hslider("freq", 220, 50, 1000, 0.01);
gate = button("gate");
pente = hslider("pente", 1, 0, 3, 0.01);
inharm = hslider("inharmonicité", 0, 0, 0.1, 0.001);
partiel(i) = os.osc(freq * n * sqrt(1 + inharm * n * n)) / pow(n, pente) with { n = i + 1; };
process = par(i, 12, partiel(i)) :> _ * en.adsr(0.01, 0.4, 0.4, 0.8, gate) * 0.2 <: _, _;

import("stdfaust.lib");
freq = hslider("freq", 110, 30, 800, 0.01);
gate = button("gate");
coupure = hslider("coupure [unit:Hz]", 1200, 80, 8000, 1) : si.smoo;
reso = hslider("résonance", 3, 0.7, 20, 0.1);
env = en.adsr(0.005, 0.2, 0.6, 0.3, gate);
process = (os.sawtooth(freq) + os.sawtooth(freq * 1.005)) * 0.2 * env
  : fi.resonlp(coupure * (0.3 + env), reso, 1) <: _, _;

import("stdfaust.lib");
freq = hslider("freq", 220, 50, 1000, 0.01);
gate = button("gate");
rapport = hslider("rapport", 1, 0.25, 8, 0.01);
indice = hslider("indice", 3, 0, 15, 0.01);
env = en.adsr(0.005, 0.5, 0.3, 0.6, gate);
modulante = os.osc(freq * rapport) * indice * env * freq * rapport;
process = os.osc(freq + modulante) * env * 0.3 <: _, _;

import("stdfaust.lib");
freq = hslider("freq [unit:Hz]", 330, 50, 1000, 1);
vitesse = hslider("vitesse [unit:Hz]", 5, 0.1, 500, 0.1) : si.smoo;
profondeur = hslider("profondeur", 0.8, 0, 1, 0.01);
process = os.osc(freq) * (1 - profondeur * (0.5 + 0.5 * os.osc(vitesse))) * 0.3 <: _, _;

import("stdfaust.lib");
freq = hslider("freq", 110, 30, 600, 0.01);
gate = button("gate");
vitesse = hslider("vitesse [unit:Hz]", 0.4, 0.05, 8, 0.01);
largeur = 0.5 + 0.4 * os.osc(vitesse);
process = os.pulsetrain(freq, largeur) * en.adsr(0.01, 0.2, 0.7, 0.4, gate) * 0.2 : fi.lowpass(2, 4000) <: _, _;

import("stdfaust.lib");
freq = hslider("freq", 110, 30, 800, 0.01);
gate = button("gate");
desaccord = hslider("désaccord", 0.01, 0, 0.05, 0.001);
voix(i) = os.sawtooth(freq * (1 + desaccord * (i - 3) / 3));
process = par(i, 7, voix(i)) :> _ * en.adsr(0.05, 0.3, 0.8, 0.8, gate) * 0.08 : fi.lowpass(2, 5000) <: _, _;

import("stdfaust.lib");
couleur = nentry("couleur [style:menu{'blanc':0;'rose':1;'brun':2}]", 0, 0, 2, 1);
volume = hslider("volume", 0.2, 0, 1, 0.01) : si.smoo;
brun = no.noise : fi.pole(0.995) * 0.05;
process = no.noise * 0.5, no.pink_noise, brun : ba.selectn(3, couleur) * volume <: _, _;

import("stdfaust.lib");
centre = hslider("centre [unit:Hz]", 800, 100, 6000, 1) : si.smoo;
q = hslider("étroitesse (Q)", 5, 0.5, 80, 0.1);
volume = hslider("volume", 0.5, 0, 1, 0.01);
process = no.noise : fi.resonbp(centre, q, volume) <: _, _;

import("stdfaust.lib");
force = hslider("force", 0.5, 0, 1, 0.01);
lent(s) = no.noise : ba.sAndH(ba.pulse(ma.SR / s)) : si.smooth(ba.tau2pole(1 / s));
centre = 300 + 1500 * force * (0.5 + 0.5 * lent(1.3));
process = no.noise : fi.resonbp(centre, 3, 0.3 + 0.5 * force * (0.5 + 0.5 * lent(0.7))) <: _, _;

import("stdfaust.lib");
freq = hslider("freq", 130, 70, 400, 0.01);
gate = button("gate");
v = hslider("voyelle (a é i o ou)", 0, 0, 4, 0.01) : si.smoo;
f1 = 730, 530, 270, 570, 300 : ba.selectn(5, int(v + 0.5));
f2 = 1090, 1840, 2290, 840, 870 : ba.selectn(5, int(v + 0.5));
f3 = 2440, 2480, 3010, 2410, 2240 : ba.selectn(5, int(v + 0.5));
source = os.sawtooth(freq * (1 + 0.006 * os.osc(5))) * en.adsr(0.05, 0.1, 0.9, 0.3, gate);
process = source <: fi.resonbp(f1 : si.smoo, 10, 1), fi.resonbp(f2 : si.smoo, 12, 0.5), fi.resonbp(f3 : si.smoo, 14, 0.3) :> _ * 0.15 <: _, _;

import("stdfaust.lib");
freq = hslider("freq", 220, 50, 1000, 0.01);
gate = button("gate");
amorti = hslider("amortissement", 0.4, 0, 1, 0.01);
process = gate : ba.impulsify : pm.ks(pm.f2l(freq), amorti) * 0.6 <: _, _;

import("stdfaust.lib");
freq = hslider("freq", 80, 40, 300, 0.01);
gate = button("gate");
position = hslider("position de frappe", 0.3, 0, 1, 0.01);
force = hslider("force", 0.8, 0, 1, 0.01);
process = gate : ba.impulsify : pm.djembe(freq, position, 0.5, force) * 2 <: _, _;

import("stdfaust.lib");
freq = hslider("freq", 440, 100, 2000, 0.01);
gate = button("gate");
position = hslider("position de frappe", 1, 0, 4, 1);
dur = hslider("dureté du maillet", 0.5, 0, 1, 0.01);
process = gate : ba.impulsify : pm.marimba(freq, position, dur * 7000 + 1000, 0.25, 1) * 2 <: _, _;

import("stdfaust.lib");
freq = hslider("freq", 440, 200, 1500, 0.01);
gate = button("gate");
pression = hslider("pression", 0.9, 0.5, 1.2, 0.01);
process = pm.fluteModel(pm.f2l(freq), 0.5, pression * en.asr(0.05, 1, 0.1, gate)) * 0.4 <: _, _;

import("stdfaust.lib");
gate = button("gate");
position = hslider("position de frappe", 0, 0, 6, 1);
dur = hslider("dureté", 0.5, 0, 1, 0.01);
process = gate : ba.impulsify : pm.frenchBell(position, dur * 7000 + 1000, 0.5, 1) * 0.3 <: _, _;

import("stdfaust.lib");
tempo = hslider("tempo [unit:BPM]", 90, 40, 220, 1);
temps = hslider("temps par mesure", 4, 2, 7, 1);
marche = checkbox("marche");
battement = ba.beat(tempo) * marche;
compte = battement : ba.pulse_countup_loop(temps - 1, 1);
clic = battement : en.ar(0.001, 0.05) * os.osc(select2(compte == 0, 1000, 1600));
process = clic * 0.5 <: _, _;

import("stdfaust.lib");
tempo = hslider("tempo [unit:BPM]", 100, 60, 180, 1);
marche = checkbox("marche");
pas = ba.beat(tempo * 4) * marche;
n = pas : ba.pulse_countup_loop(15, 1);
motif(m) = (m >> (15 - n)) & 1;
egc = pas * motif(34984) : en.ar(0.001, 0.25);
gc = os.osc(50 + 120 * egc) * egc * 0.7;
cc = pas * motif(2056) : en.ar(0.001, 0.15) * (no.noise : fi.highpass(2, 1500)) * 0.5;
ch = pas * motif(43690) : en.ar(0.001, 0.04) * (no.noise : fi.highpass(2, 7000)) * 0.3;
process = (gc + cc + ch) * 0.55 <: _, _;

import("stdfaust.lib");
tempo = hslider("tempo [unit:BPM]", 60, 30, 120, 1);
marche = checkbox("marche");
coup(f, t) = ba.beat(t) * marche : en.ar(0.001, 0.12) * os.osc(f);
process = (coup(220, tempo * 2) + coup(660, tempo * 3)) * 0.4 <: _, _;

import("stdfaust.lib");
tempo = hslider("tempo [unit:BPM]", 120, 60, 300, 1);
mineur = checkbox("mineur");
marche = checkbox("marche");
pas = ba.beat(tempo * 2) * marche;
n = pas : ba.pulse_countup_loop(3, 1);
demi = 0, select2(mineur, 4, 3), 7, 12 : ba.selectn(4, n);
note = 57 + demi : ba.midikey2hz;
process = os.triangle(note) * (pas : en.ar(0.005, 0.3)) * 0.4 <: _, _;

import("stdfaust.lib");
temps = hslider("temps [unit:s]", 0.35, 0.05, 1.5, 0.01);
retour = hslider("retour", 0.5, 0, 0.95, 0.01);
process = _ <: _, ef.echo(2, temps, retour) * 0.6 :> _ * 0.6 <: _, _;

import("stdfaust.lib");
taille = hslider("taille de la salle", 0.8, 0, 0.98, 0.01);
melange = hslider("mélange", 0.4, 0, 1, 0.01);
process = _ <: (_ * (1 - melange) <: _, _), (_ <: re.stereo_freeverb(taille, 0.5, 0.5, 23) : _ * melange * 0.25, _ * melange * 0.25) :> _, _;

import("stdfaust.lib");
f = hslider("fréquence [unit:Hz]", 60, 10, 400, 1);
process = _ * os.osc(f) * 2 <: _, _;

import("stdfaust.lib");
gain = hslider("gain", 0.5, 0, 1, 0.01);
process = _ : ef.cubicnl(gain, 0) * 0.7 <: _, _;

import("stdfaust.lib");
demitons = hslider("décalage [unit:demi-tons]", 7, -12, 12, 1);
process = _ <: _ * 0.6, ef.transpose(2048, 512, demitons) :> _ <: _, _;

import("stdfaust.lib");
vitesse = hslider("vitesse [unit:Hz]", 0.25, 0, 3, 0.01);
p = 0.5 + 0.5 * os.osc(vitesse);
son = os.sawtooth(220) * 0.2 : fi.lowpass(2, 1500);
process = son <: _ * sqrt(1 - p), _ * sqrt(p);

import("stdfaust.lib");
vitesse = hslider("vitesse de passage", 0.2, 0.05, 1, 0.01);
x = os.lf_sawpos(vitesse) * 2 - 1;
dist = sqrt(x * x + 0.01);
v = x / dist;
hauteur = 660 * (1 - 0.25 * v);
process = os.square(hauteur) * 0.15 / (dist * 2 + 0.3) : fi.lowpass(2, 3000) <: _ * (0.5 - 0.5 * x), _ * (0.5 + 0.5 * x);

import("stdfaust.lib");
racine = hslider("racine [unit:Hz]", 110, 55, 220, 0.01);
lenteur = hslider("lenteur", 0.05, 0.01, 0.5, 0.01);
voix(r, k) = os.sawtooth(racine * r) : fi.resonlp(500 + 1500 * (0.5 + 0.5 * os.osc(lenteur * k)), 2, 0.08);
process = (voix(1, 1) + voix(1.5, 1.3) + voix(2.4, 0.7) + voix(3, 1.7)) * 0.15 <: re.stereo_freeverb(0.9, 0.5, 0.5, 23);

import("stdfaust.lib");
tempo = hslider("tempo [unit:BPM]", 80, 30, 200, 1);
marche = checkbox("marche");
pas = ba.beat(tempo * 2) * marche;
hasard = no.noise : ba.sAndH(pas) : abs;
note = 0, 2, 4, 7, 9, 12, 14, 16 : ba.selectn(8, int(hasard * 7.99));
f = 69 + note : ba.midikey2hz;
env = pas : en.ar(0.002, 2.5);
cloche = os.osc(f + os.osc(f * 3.5) * f * 2 * env) * env * 0.25;
process = cloche * 0.12 <: re.stereo_freeverb(0.85, 0.4, 0.5, 23);

import("stdfaust.lib");
vitesse = hslider("vitesse [unit:Hz]", 0.1, 0.02, 1, 0.01);
f = 150 + 1000 * (0.5 - 0.5 * os.osc(vitesse));
process = os.triangle(f) * 0.06 <: re.stereo_freeverb(0.7, 0.5, 0.5, 23);

