import("stdfaust.lib");
hauteur = hslider("hauteur", 440, 100, 1000, 1) : si.smoo;
marche = checkbox("jouer") : si.smoo;
process = os.osc(hauteur) * 0.15 * marche;

import("stdfaust.lib");
note = hslider("note", 110, 55, 440, 1) : si.smoo;
h(i) = vslider("h%i", (i == 0), 0, 1, 0.01) : si.smoo;
marche = checkbox("jouer") : si.smoo;
process = par(i, 8, os.osc(note * (i + 1)) * h(i)) :> *(0.12 * marche);

import("stdfaust.lib");
note = hslider("note", 330, 100, 1000, 1);
resonance = hslider("resonance", 2, 0.2, 6, 0.1);
metal = hslider("metal", 1, 0, 1, 0.01);
frappe = button("frapper");
partiel(harm, inharm, d, a) = os.osc(note * (harm + metal * (inharm - harm))) * en.ar(0.001, resonance * d, frappe) * a;
process = (partiel(1, 1, 1, 0.5) + partiel(2, 2.76, 0.5, 0.3) + partiel(3, 5.4, 0.25, 0.15) + partiel(4, 8.93, 0.12, 0.08)) * 0.4;

import("stdfaust.lib");
duree = hslider("salle", 2, 0.3, 8, 0.1);
process = pm.nylonGuitar_ui_MIDI <: re.zita_rev1_stereo(20, 200, 6000, duree, duree * 0.8, 48000) : *(3), *(3);

import("stdfaust.lib");
vitesse = hslider("vitesse", 0.05, 0.01, 0.5, 0.01);
densite = hslider("densite", 8, 1, 16, 1) : si.smoo;
marche = checkbox("jouer") : si.smoo;
voix(i) = os.sawtooth(200 + i * 45 + 150 * os.osc(vitesse * (1 + i * 0.13))) * (i < densite);
process = par(i, 16, voix(i)) :> fi.lowpass(2, 2500) * 0.03 * marche;
